From 8a8a3232abac5b972058a5f2cb3e33199d2a8648 Mon Sep 17 00:00:00 2001
From: Haoxiang Li <haoxiang_li2024@163.com>
Date: Wed, 8 Oct 2025 16:55:03 +0800
Subject: [PATCH] media: mtk-mdp: Fix error handling in probe function

Add mtk_mdp_unregister_m2m_device() on the error handling path to prevent
resource leak.

Add check for the return value of vpu_get_plat_device() to prevent null
pointer dereference. And vpu_get_plat_device() increases the reference
count of the returned platform device. Add platform_device_put() to
prevent reference leak.

Fixes: c8eb2d7e8202 ("[media] media: Add Mediatek MDP Driver")
Cc: stable@vger.kernel.org
Signed-off-by: Haoxiang Li <haoxiang_li2024@163.com>
Signed-off-by: Nicolas Dufresne <nicolas.dufresne@collabora.com>
Signed-off-by: Hans Verkuil <hverkuil+cisco@kernel.org>

diff --git a/drivers/media/platform/mediatek/mdp/mtk_mdp_core.c b/drivers/media/platform/mediatek/mdp/mtk_mdp_core.c
index 80fdc6ff57e0..f78fa30f1864 100644
--- a/drivers/media/platform/mediatek/mdp/mtk_mdp_core.c
+++ b/drivers/media/platform/mediatek/mdp/mtk_mdp_core.c
@@ -194,11 +194,17 @@ static int mtk_mdp_probe(struct platform_device *pdev)
 	}

 	mdp->vpu_dev = vpu_get_plat_device(pdev);
+	if (!mdp->vpu_dev) {
+		dev_err(&pdev->dev, "Failed to get vpu device\n");
+		ret = -ENODEV;
+		goto err_vpu_get_dev;
+	}
+
 	ret = vpu_wdt_reg_handler(mdp->vpu_dev, mtk_mdp_reset_handler, mdp,
 				  VPU_RST_MDP);
 	if (ret) {
 		dev_err(&pdev->dev, "Failed to register reset handler\n");
-		goto err_m2m_register;
+		goto err_reg_handler;
 	}

 	platform_set_drvdata(pdev, mdp);
@@ -206,7 +212,7 @@ static int mtk_mdp_probe(struct platform_device *pdev)
 	ret = vb2_dma_contig_set_max_seg_size(&pdev->dev, DMA_BIT_MASK(32));
 	if (ret) {
 		dev_err(&pdev->dev, "Failed to set vb2 dma mag seg size\n");
-		goto err_m2m_register;
+		goto err_reg_handler;
 	}

 	pm_runtime_enable(dev);
@@ -214,6 +220,12 @@ static int mtk_mdp_probe(struct platform_device *pdev)

 	return 0;

+err_reg_handler:
+	platform_device_put(mdp->vpu_dev);
+
+err_vpu_get_dev:
+	mtk_mdp_unregister_m2m_device(mdp);
+
 err_m2m_register:
 	v4l2_device_unregister(&mdp->v4l2_dev);

-- 
2.34.1

Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
media: mtk-mdp: Fix error handling in probe function

Add mtk_mdp_unregister_m2m_device() on the error handling path to prevent
resource leak.

Add check for the return value of vpu_get_plat_device() to prevent null
pointer dereference. And vpu_get_plat_device() increases the reference
count of the returned platform device. Add platform_device_put() to
prevent reference leak.

Fixes: c8eb2d7e8202 ("[media] media: Add Mediatek MDP Driver")
Cc: stable@vger.kernel.org
Signed-off-by: Haoxiang Li <haoxiang_li2024@163.com>
Signed-off-by: Nicolas Dufresne <nicolas.dufresne@collabora.com>
Signed-off-by: Hans Verkuil <hverkuil+cisco@kernel.org>

Here is the root cause:
Incomplete error handling in the probe function of mtk_mdp_core.c. After successfully registering the M2M device, subsequent failures (e.g., vpu_get_plat_device returning NULL, vpu_wdt_reg_handler or vb2_dma_contig_set_max_seg_size failing) did not call mtk_mdp_unregister_m2m_device(), leading to a resource leak. Additionally, the return value of vpu_get_plat_device() was not checked, risking null pointer dereference, and its returned platform device reference was not released on error paths, causing a reference leak.

Here is the patch:

 static int mtk_mdp_probe(struct platform_device *pdev)
 {
 	struct mtk_mdp_dev *mdp;
 	struct device *dev = &pdev->dev;
 	struct device_node *node, *parent;
 	struct mtk_mdp_comp *comp, *comp_temp;
 	int ret = 0;

 	mdp = devm_kzalloc(dev, sizeof(*mdp), GFP_KERNEL);
 	if (!mdp)
 		return -ENOMEM;

 	mdp->id = pdev->id;
 	mdp->pdev = pdev;
 	INIT_LIST_HEAD(&mdp->comp_list);
 	INIT_LIST_HEAD(&mdp->ctx_list);

 	mutex_init(&mdp->lock);
 	mutex_init(&mdp->vpulock);

 	/* Old dts had the components as child nodes */
 	node = of_get_next_child(dev->of_node, NULL);
 	if (node) {
 		of_node_put(node);
 		parent = dev->of_node;
 		dev_warn(dev, "device tree is out of date\n");
 	} else {
 		parent = dev->of_node->parent;
 	}

 	/* Iterate over sibling MDP function blocks */
 	for_each_child_of_node(parent, node) {
 		const struct of_device_id *of_id;
 		enum mtk_mdp_comp_type comp_type;

 		of_id = of_match_node(mtk_mdp_comp_dt_ids, node);
 		if (!of_id)
 			continue;

 		if (!of_device_is_available(node)) {
 			dev_err(dev, "Skipping disabled component %pOF\n",
 				node);
 			continue;
 		}

 		comp_type = (uintptr_t)of_id->data;

 		comp = devm_kzalloc(dev, sizeof(*comp), GFP_KERNEL);
 		if (!comp) {
 			ret = -ENOMEM;
 			of_node_put(node);
 			goto err_comp;
 		}

 		ret = mtk_mdp_comp_init(dev, node, comp, comp_type);
 		if (ret) {
 			of_node_put(node);
 			goto err_comp;
 		}

 		mtk_mdp_register_component(mdp, comp);
 	}

 	mdp->job_wq = create_singlethread_workqueue(MTK_MDP_MODULE_NAME);
 	if (!mdp->job_wq) {
 		dev_err(&pdev->dev, "unable to alloc job workqueue\n");
 		ret = -ENOMEM;
 		goto err_alloc_job_wq;
 	}

 	mdp->wdt_wq = create_singlethread_workqueue("mdp_wdt_wq");
 	if (!mdp->wdt_wq) {
 		dev_err(&pdev->dev, "unable to alloc wdt workqueue\n");
 		ret = -ENOMEM;
 		goto err_alloc_wdt_wq;
 	}
 	INIT_WORK(&mdp->wdt_work, mtk_mdp_wdt_worker);

 	ret = v4l2_device_register(dev, &mdp->v4l2_dev);
 	if (ret) {
 		dev_err(&pdev->dev, "Failed to register v4l2 device\n");
 		ret = -EINVAL;
 		goto err_dev_register;
 	}

 	ret = mtk_mdp_register_m2m_device(mdp);
 	if (ret) {
 		v4l2_err(&mdp->v4l2_dev, "Failed to init mem2mem device\n");
 		goto err_m2m_register;
 	}

 	mdp->vpu_dev = vpu_get_plat_device(pdev);
+	if (!mdp->vpu_dev) {
+		dev_err(&pdev->dev, "Failed to get vpu device\n");
+		ret = -ENODEV;
+		goto err_vpu_get_dev;
+	}
+
 	ret = vpu_wdt_reg_handler(mdp->vpu_dev, mtk_mdp_reset_handler, mdp,
 				  VPU_RST_MDP);
 	if (ret) {
 		dev_err(&pdev->dev, "Failed to register reset handler\n");
-		goto err_m2m_register;
+		goto err_reg_handler;
 	}

 	platform_set_drvdata(pdev, mdp);

 	ret = vb2_dma_contig_set_max_seg_size(&pdev->dev, DMA_BIT_MASK(32));
 	if (ret) {
 		dev_err(&pdev->dev, "Failed to set vb2 dma mag seg size\n");
-		goto err_m2m_register;
+		goto err_reg_handler;
 	}

 	pm_runtime_enable(dev);
 	dev_dbg(dev, "mdp-%d registered successfully\n", mdp->id);

 	return 0;

+err_reg_handler:
+	platform_device_put(mdp->vpu_dev);
+
+err_vpu_get_dev:
+	mtk_mdp_unregister_m2m_device(mdp);
+
 err_m2m_register:
 	v4l2_device_unregister(&mdp->v4l2_dev);

 err_dev_register:
 	destroy_workqueue(mdp->wdt_wq);

 err_alloc_wdt_wq:
 	destroy_workqueue(mdp->job_wq);

 err_alloc_job_wq:

 err_comp:
 	list_for_each_entry_safe(comp, comp_temp, &mdp->comp_list, node) {
 		mtk_mdp_unregister_component(mdp, comp);
 		mtk_mdp_comp_deinit(dev, comp);
 	}

 	dev_dbg(dev, "err %d\n", ret);
 	return ret;
 }



Provide a response strictly in the following format:

The code statements that lead to the bug are:
<text>
<text>
...
<text>
Reason:
<text>
The code statements that fix the bug are:
<text>
<text>
...
<text>
Reason:
<text>

The code statements that lead to the bug are:
```c
mdp->vpu_dev = vpu_get_plat_device(pdev);
```
```c
ret = vpu_wdt_reg_handler(...);
if (ret) {
    ...
    goto err_m2m_register;
}
```
```c
ret = vb2_dma_contig_set_max_seg_size(...);
if (ret) {
    ...
    goto err_m2m_register;
}
```
Reason:  
- The return value of `vpu_get_plat_device()` is not checked for NULL, which can cause a null pointer dereference later.  
- After `mtk_mdp_register_m2m_device()` succeeds, a failure in `vpu_wdt_reg_handler()` or `vb2_dma_contig_set_max_seg_size()` jumps to `err_m2m_register`. That label does not call `mtk_mdp_unregister_m2m_device()` nor `platform_device_put()`, resulting in a resource leak (M2M device not unregistered) and a reference leak (vpu device reference not released).

The code statements that fix the bug are:
```c
if (!mdp->vpu_dev) {
    dev_err(&pdev->dev, "Failed to get vpu device\n");
    ret = -ENODEV;
    goto err_vpu_get_dev;
}
```
```c
ret = vpu_wdt_reg_handler(...);
if (ret) {
    ...
    goto err_reg_handler;
}
```
```c
err_reg_handler:
    platform_device_put(mdp->vpu_dev);

err_vpu_get_dev:
    mtk_mdp_unregister_m2m_device(mdp);
```
Reason:  
- The NULL check for `vpu_get_plat_device()` prevents a null pointer dereference and jumps to a new cleanup label.  
- The goto targets are changed to `err_reg_handler`, which correctly releases the vpu device reference via `platform_device_put()`. Then `err_vpu_get_dev` ensures `mtk_mdp_unregister_m2m_device()` is called to avoid the M2M resource leak.  
- The new error labels chain properly so that all allocated resources (vpu device, M2M device, v4l2 device, workqueues, components) are freed in the correct order on any failure path.

